create extension if not exists pgcrypto;
create table public.perfis(id uuid primary key references auth.users(id) on delete cascade,nome text not null default 'Usuário',papel text not null default 'funcionario' check(papel in('administrador','funcionario')),ativo boolean not null default true,criado_em timestamptz default now(),atualizado_em timestamptz default now());
create table public.categorias(id uuid primary key default gen_random_uuid(),nome text not null unique,ativo boolean not null default true,criado_em timestamptz default now());
create table public.produtos(id uuid primary key default gen_random_uuid(),categoria_id uuid references public.categorias(id) on delete set null,nome text not null,descricao text,preco numeric(10,2) not null check(preco>=0),disponivel boolean not null default true,ativo boolean not null default true,criado_em timestamptz default now(),atualizado_em timestamptz default now());
create table public.pedidos(id uuid primary key default gen_random_uuid(),numero bigint generated by default as identity unique,usuario_id uuid not null references public.perfis(id),status text not null default 'recebido' check(status in('recebido','em_preparo','pronto','entregue','cancelado')),subtotal numeric(10,2) not null default 0,desconto numeric(10,2) not null default 0,total numeric(10,2) not null default 0,observacao text,motivo_cancelamento text,criado_em timestamptz default now(),atualizado_em timestamptz default now());
create table public.itens_pedido(id uuid primary key default gen_random_uuid(),pedido_id uuid not null references public.pedidos(id),produto_id uuid references public.produtos(id) on delete set null,nome_produto text not null,quantidade integer not null check(quantidade>0),preco_unitario numeric(10,2) not null check(preco_unitario>=0),subtotal numeric(10,2) not null check(subtotal>=0),observacao text,criado_em timestamptz default now());
create table public.formas_pagamento(id uuid primary key default gen_random_uuid(),nome text not null unique,ativo boolean not null default true);
create table public.pagamentos(id uuid primary key default gen_random_uuid(),pedido_id uuid not null references public.pedidos(id),forma_pagamento_id uuid not null references public.formas_pagamento(id),valor numeric(10,2) not null check(valor>0),status text not null default 'confirmado' check(status in('pendente','confirmado','estornado')),usuario_id uuid not null references public.perfis(id),criado_em timestamptz default now());
create table public.historico_pedidos(id uuid primary key default gen_random_uuid(),pedido_id uuid not null references public.pedidos(id),usuario_id uuid not null references public.perfis(id),status_anterior text,status_novo text not null,motivo text,criado_em timestamptz default now());
insert into public.formas_pagamento(nome) values('Dinheiro'),('Pix'),('Cartão de débito'),('Cartão de crédito') on conflict do nothing;

create function public.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.perfis(id,nome,papel) values(new.id,coalesce(new.raw_user_meta_data->>'nome',split_part(coalesce(new.email,''),'@',1),'Usuário'),'funcionario') on conflict(id) do nothing; return new; end $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create function public.usuario_ativo() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.perfis where id=(select auth.uid()) and ativo=true); $$;
create function public.eh_administrador() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.perfis where id=(select auth.uid()) and ativo=true and papel='administrador'); $$;
grant execute on function public.usuario_ativo(),public.eh_administrador() to authenticated;

create function public.criar_pedido(p_observacao text,p_itens jsonb) returns uuid language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid(); pid uuid; it jsonb; prod public.produtos%rowtype; qtd int; sub numeric(10,2); total numeric(10,2):=0;
begin
 if u is null or not public.usuario_ativo() then raise exception 'Usuário não autorizado'; end if;
 if jsonb_typeof(p_itens)<>'array' or jsonb_array_length(p_itens)=0 then raise exception 'Pedido vazio'; end if;
 insert into public.pedidos(usuario_id,observacao) values(u,nullif(trim(p_observacao),'')) returning id into pid;
 for it in select value from jsonb_array_elements(p_itens) loop
  qtd:=(it->>'quantidade')::int; if qtd<=0 then raise exception 'Quantidade inválida'; end if;
  select * into prod from public.produtos where id=(it->>'produto_id')::uuid and ativo and disponivel for share;
  if not found then raise exception 'Produto indisponível'; end if;
  sub:=prod.preco*qtd; total:=total+sub;
  insert into public.itens_pedido(pedido_id,produto_id,nome_produto,quantidade,preco_unitario,subtotal) values(pid,prod.id,prod.nome,qtd,prod.preco,sub);
 end loop;
 update public.pedidos set subtotal=total,total=total where id=pid;
 insert into public.historico_pedidos(pedido_id,usuario_id,status_novo) values(pid,u,'recebido');
 return pid;
end $$;

create function public.atualizar_status_pedido(p_pedido_id uuid,p_novo_status text,p_motivo text default null) returns void language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid(); anterior text;
begin
 if u is null or not public.usuario_ativo() then raise exception 'Usuário não autorizado'; end if;
 select status into anterior from public.pedidos where id=p_pedido_id for update;
 if not found then raise exception 'Pedido não encontrado'; end if;
 if anterior in('entregue','cancelado') then raise exception 'Pedido encerrado'; end if;
 if p_novo_status='cancelado' then if nullif(trim(p_motivo),'') is null then raise exception 'Informe o motivo'; end if;
 elsif not ((anterior='recebido' and p_novo_status='em_preparo') or (anterior='em_preparo' and p_novo_status='pronto') or (anterior='pronto' and p_novo_status='entregue')) then raise exception 'Transição inválida'; end if;
 update public.pedidos set status=p_novo_status,motivo_cancelamento=case when p_novo_status='cancelado' then trim(p_motivo) else motivo_cancelamento end where id=p_pedido_id;
 insert into public.historico_pedidos(pedido_id,usuario_id,status_anterior,status_novo,motivo) values(p_pedido_id,u,anterior,p_novo_status,nullif(trim(p_motivo),''));
end $$;

create function public.registrar_pagamento(p_pedido_id uuid,p_forma_pagamento_id uuid,p_valor numeric) returns uuid language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid(); total_p numeric(10,2); pago numeric(10,2); st text; pid uuid;
begin
 if u is null or not public.usuario_ativo() then raise exception 'Usuário não autorizado'; end if;
 select total,status into total_p,st from public.pedidos where id=p_pedido_id for update;
 if not found or st='cancelado' then raise exception 'Pedido inválido ou cancelado'; end if;
 if p_valor is null or p_valor<=0 then raise exception 'Valor inválido'; end if;
 if not exists(select 1 from public.formas_pagamento where id=p_forma_pagamento_id and ativo) then raise exception 'Forma inválida'; end if;
 select coalesce(sum(valor),0) into pago from public.pagamentos where pedido_id=p_pedido_id and status='confirmado';
 if round(pago+p_valor,2)>total_p then raise exception 'Pagamento maior que saldo'; end if;
 insert into public.pagamentos(pedido_id,forma_pagamento_id,valor,usuario_id) values(p_pedido_id,p_forma_pagamento_id,p_valor,u) returning id into pid; return pid;
end $$;
revoke all on function public.criar_pedido(text,jsonb),public.atualizar_status_pedido(uuid,text,text),public.registrar_pagamento(uuid,uuid,numeric) from public;
grant execute on function public.criar_pedido(text,jsonb),public.atualizar_status_pedido(uuid,text,text),public.registrar_pagamento(uuid,uuid,numeric) to authenticated;

alter table public.perfis enable row level security;alter table public.categorias enable row level security;alter table public.produtos enable row level security;alter table public.pedidos enable row level security;alter table public.itens_pedido enable row level security;alter table public.formas_pagamento enable row level security;alter table public.pagamentos enable row level security;alter table public.historico_pedidos enable row level security;
create policy perfil_read on public.perfis for select to authenticated using(id=(select auth.uid()) or public.eh_administrador());
create policy perfil_admin_update on public.perfis for update to authenticated using(public.eh_administrador()) with check(public.eh_administrador());
create policy cat_read on public.categorias for select to authenticated using(ativo or public.eh_administrador());
create policy cat_admin_insert on public.categorias for insert to authenticated with check(public.eh_administrador());
create policy cat_admin_update on public.categorias for update to authenticated using(public.eh_administrador()) with check(public.eh_administrador());
create policy prod_read on public.produtos for select to authenticated using((ativo and public.usuario_ativo()) or public.eh_administrador());
create policy prod_admin_insert on public.produtos for insert to authenticated with check(public.eh_administrador());
create policy prod_admin_update on public.produtos for update to authenticated using(public.eh_administrador()) with check(public.eh_administrador());
create policy pedido_read on public.pedidos for select to authenticated using(public.usuario_ativo());
create policy item_read on public.itens_pedido for select to authenticated using(public.usuario_ativo());
create policy forma_read on public.formas_pagamento for select to authenticated using(ativo or public.eh_administrador());
create policy forma_admin_insert on public.formas_pagamento for insert to authenticated with check(public.eh_administrador());
create policy pagamento_read on public.pagamentos for select to authenticated using(public.usuario_ativo());
create policy historico_read on public.historico_pedidos for select to authenticated using(public.usuario_ativo());
revoke insert,update,delete on public.pedidos,public.itens_pedido,public.pagamentos,public.historico_pedidos from anon,authenticated;
grant select on public.perfis,public.categorias,public.produtos,public.pedidos,public.itens_pedido,public.formas_pagamento,public.pagamentos,public.historico_pedidos to authenticated;
grant insert,update on public.categorias,public.produtos,public.formas_pagamento to authenticated;
grant update on public.perfis to authenticated;

do $$ begin alter publication supabase_realtime add table public.pedidos; exception when others then null; end $$;
